import {seq,choose,read,book} from './more-stories.js';

// Histórias diferentes podem compartilhar a ilustração de um mesmo cenário.
const make=(id,title,level,art,alt,pages,finals,summary)=>{
  const result=book(id,title,level,alt,pages,finals,summary);
  result.cover=result.endingImage=`${art}.webp`;
  result.pages.forEach(page=>page.image=`${art}.webp`);
  return result;
};
const count=(chapter,narration,instruction,amount,icon,noun,options,hint)=>({chapter,narration,instruction,type:'count',count:amount,countIcon:icon,countNoun:noun,answer:String(amount),choices:options.map(n=>({label:String(n)})),hint,success:'Você contou! Vamos continuar a aventura.'});

